import time
from google.cloud import monitoring_v3

def obter_metricas_execucao(id_projeto, nome_funcao):
    cliente = monitoring_v3.MetricServiceClient()
    nome_projeto = f'projects/{id_projeto}'
    filtro_metrica = (
        f'resource.type="cloud_function" '
        f'AND resource.labels.function_name="{nome_funcao}"'
    )
    intervalo = monitoring_v3.TimeInterval({
        'end_time': {'seconds': int(time.time())},
        'start_time': {'seconds': int(time.time()) - 3600}
    })
    return cliente.list_time_series(request={'name': nome_projeto, 'filter': filtro_metrica, 'interval': intervalo})
